"""Rebuild the bilingual cover gallery from the publication manifest."""
import html,json
from pathlib import Path
root=Path(__file__).resolve().parent
m=json.loads((root/'covers/manifest.json').read_text());esc=html.escape
out=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>English / Hebrew game boxes</title><style>body{background:#12141b;color:#edf0f8;font:16px system-ui;margin:0;padding:32px}header{max-width:1100px;margin:0 auto 32px}p{color:#b9c0d4;line-height:1.6}input{background:#242936;color:white;padding:14px;border:1px solid #586177;border-radius:8px;width:min(90%,500px)}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:24px}article{background:#1c202b;padding:20px;border-radius:14px}article[hidden]{display:none}h2{font-size:20px;margin:0 0 8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}figure{margin:0}img{width:100%;height:340px;object-fit:contain;background:#101219}figcaption{margin-top:8px;font-size:14px}a{color:#8ac7ff}small{color:#b9c0d4}@media(max-width:550px){body{padding:12px}main{grid-template-columns:1fr}img{height:250px}}</style><header><h1>English / Hebrew game boxes</h1>''',f'<p>{len(m["games"])} pairs · English when the patch is absent, Hebrew when installed.</p><p>149 pairs added from the JSON catalog. <a href="imports/2026-10-25/review.html">View import details and unresolved entries</a>.</p><input id="search" aria-label="Search games" placeholder="Search English or Hebrew title"><p id="count"></p></header><main>']
for g in m['games']:
 title=g.get('title',g['game_id']);he=g.get('title_he','');out.append(f'<article data-search="{esc(title+" "+he,quote=True)}"><h2>{esc(title)}</h2><div dir="rtl">{esc(he)}</div><div class="pair">')
 for lang,label in [('en','English original'),('he','Hebrew')]:
  a=g['covers'][lang];out.append(f'<figure><a href="{esc(a["file"],quote=True)}"><img loading="lazy" src="{esc(a["file"],quote=True)}" alt="{esc(title+" — "+label,quote=True)}"></a><figcaption>{label} · <a href="{esc(a["original_url"],quote=True)}">Cloudflare</a></figcaption></figure>')
 out.append('</div></article>')
out.append('''</main><script>function update(){let q=document.querySelector('#search').value.toLowerCase(),n=0;document.querySelectorAll('article').forEach(a=>{a.hidden=!a.dataset.search.toLowerCase().includes(q);if(!a.hidden)n++});document.querySelector('#count').textContent=n+' games'}document.querySelector('#search').oninput=update;update()</script></html>''');(root/'review-pairs.html').write_text(''.join(out));print(len(m['games']),'pairs')
